verification_harness:
param([string]$Before, [string]$After)
$ErrorActionPreference = 'Stop'
function Get-TokenFingerprint {
    param([string]$Path)
    $tokens = $null; $errors = $null
    [void][Management.Automation.Language.Parser]::ParseFile($Path, [ref]$tokens, [ref]$errors)
    if ($errors.Count) { throw ($errors | Out-String) }
    $semantic = @($tokens | Where-Object { [string]$_.Kind -notin @('Comment','NewLine','LineContinuation','EndOfInput') } | ForEach-Object { [ordered]@{ kind = [string]$_.Kind; text = $_.Text } })
    $bytes = [Text.UTF8Encoding]::new($false).GetBytes(($semantic | ConvertTo-Json -Depth 4 -Compress))
    $hash = [Security.Cryptography.SHA256]::Create()
    try { [pscustomobject]@{ tokenCount = $semantic.Count; sha256 = [BitConverter]::ToString($hash.ComputeHash($bytes)).Replace('-','').ToLowerInvariant() } }
    finally { $hash.Dispose() }
}
$a = Get-TokenFingerprint -Path $Before; $b = Get-TokenFingerprint -Path $After
if ($a.sha256 -ne $b.sha256 -or $a.tokenCount -ne $b.tokenCount) { throw 'Executable tokens changed in help correction.' }
[pscustomobject]@{ shell = [string]$PSVersionTable.PSVersion; parserPassed = $true; executableTokensUnchanged = $true; before = $a; after = $b } | ConvertTo-Json -Depth 5 -Compress
